//! A profile config generated by Home Manager's `configMode = "managed"`
//! (spec: distribution-and-update, NixOS and Home Manager modules): every
//! writer refuses with exit 77 naming the option, and `config.toml` stays
//! as the activation wrote it.

mod common;

#[test]
fn a_home_manager_generated_config_is_read_only() {
    let home = common::mock_home();
    let profile = home.path().join("profiles/default");
    std::fs::write(
        profile.join("config.generated.toml"),
        "generator = \"Home Manager\"\noption = \"programs.prometheus.settings\"\n",
    )
    .unwrap();
    let before = std::fs::read(profile.join("config.toml")).unwrap();
    for args in [
        &["config", "set", "model.default", "gpt-5"][..],
        &["config", "unset", "model.default"],
    ] {
        let out = common::run(home.path(), args);
        assert_eq!(
            out.status.code(),
            Some(77),
            "{args:?}: {}",
            common::stderr(&out)
        );
        let stderr = common::stderr(&out);
        assert!(
            stderr.contains("config.toml is generated by Home Manager"),
            "{stderr}"
        );
        assert!(
            stderr.contains("change programs.prometheus.settings instead"),
            "{stderr}"
        );
    }
    assert_eq!(std::fs::read(profile.join("config.toml")).unwrap(), before);
    assert!(
        common::ok(&common::run(
            home.path(),
            &["config", "get", "model.default"]
        ))
        .contains("mock")
    );
}
